SELECT U.numero_documento numeroDocumento, U.codigo_planilla codigoPlanilla, U.nombres, U.apellidos, U.fecha_creacion fechaCreacion, U.regimen, U.cargo, U.cod_red codRed, R.descripcion descripcionRed, U.cod_unidad codUnidad, UO.descripcion descripcionUnidad, U.sexo FROM usuario U INNER JOIN red_personal R ON U.cod_red = R.cod_red LEFT JOIN unidad_organizativa UO ON U.cod_unidad = UO.cod_unidad WHERE U.cod_red IN
#{codRed}
AND U.id_estado_usuario = '02' AND U.es_activo = true ORDER BY U.fecha_creacion DESC LIMIT
NULL
#{limite}
